```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure is a value; an allowlist refusal traps at the boundary.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        let message = format!("heartbeat at {seconds}: fetched {fetched} chars from {feed_url}");
        let notified = notifier::notify(&message);

        // The contract requires notified == true on every output, so a refused
        // notification must not produce a report.
        if !notified {
            panic!("notifier refused the heartbeat; no report can satisfy notified == true");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
```

I did not add the `last-input` store write. The `with` clause grants only `http-client`, `notifier`, and `wall-clock`, and the platform approval doesn't change that grant. Writing to the store needs a `state-rw` import, which this node doesn't have. The approval has to be reflected in the node's `with` clause before the import can be added.

